description:
Exploration question: What is the `src/scheduler` module for, and how does the rest of the app use it?

Files read (every line is numbered as `line | code`; this is everything that has been read):

`src/scheduler/index.ts`
```
1 | export { schedule } from "./queue";
2 | export { startWorker } from "./worker";
```

`src/scheduler/queue.ts`
```
1 | interface Job {
2 |   name: string;
3 |   payload: unknown;
4 |   runAt: number;
5 |   attempts: number;
6 | }
7 | 
8 | const jobs: Job[] = [];
9 | 
10 | export function schedule(name: string, payload: unknown, opts: { delayMs?: number } = {}): void {
11 |   jobs.push({ name, payload, runAt: Date.now() + (opts.delayMs ?? 0), attempts: 0 });
12 | }
13 | 
14 | export function takeDue(now: number): Job[] {
15 |   const due = jobs.filter((j) => j.runAt <= now);
16 |   for (const j of due) jobs.splice(jobs.indexOf(j), 1);
17 |   return due;
18 | }
19 | 
20 | export function requeue(job: Job, delayMs: number): void {
21 |   jobs.push({ ...job, runAt: Date.now() + delayMs, attempts: job.attempts + 1 });
22 | }
```

`src/scheduler/worker.ts`
```
1 | import { requeue, takeDue } from "./queue";
2 | import { handlers } from "../jobs/registry";
3 | 
4 | const MAX_ATTEMPTS = 3;
5 | 
6 | export function startWorker(): void {
7 |   setInterval(async () => {
8 |     for (const job of takeDue(Date.now())) {
9 |       try {
10 |         await handlers[job.name](job.payload);
11 |       } catch {
12 |         if (job.attempts + 1 < MAX_ATTEMPTS) requeue(job, 2 ** job.attempts * 1000);
13 |       }
14 |     }
15 |   }, 1000);
16 | }
```

